import clsx from 'clsx';
import type { SVGProps } from 'react';
import IconButton from '@/components/common/IconButton';

interface VintexAIButtonProps {
  /** Chamado ao clicar no botão (ex: abrir/navegar para a assistente). */
  onClick: () => void;
  /** Texto lido por leitores de tela. */
  ariaLabel?: string;
  className?: string;
}

/**
 * Botão flutuante (FAB) que abre a assistente de IA Vintex. Fixo no canto
 * inferior direito da tela pensado para a versão mobile.
 *
 * Usage:
 *   import { VintexAIButton } from '@/components/vintex-ai/VintexAIButton';
 *   <VintexAIButton onClick={() => navigate('/vintex')} />
 */
export function VintexAIButton({
  onClick,
  ariaLabel = 'Abrir assistente Vintex',
  className,
}: VintexAIButtonProps) {
  return (
    <div
      className={clsx(
        'fixed bottom-5 right-5 z-50 h-11 w-11 overflow-hidden rounded-full',
        'shadow-lg shadow-tinta/30',
        'transition-transform duration-150 ease-out active:scale-90',
        'motion-reduce:transition-none motion-reduce:active:scale-100',
        className,
      )}
    >
      <IconButton
        icon={<VintexAIIcon className="h-6 w-6" />}
        onClick={onClick}
        ariaLabel={ariaLabel}
        variant="primary"
      />
    </div>
  );
}

